import{_ as o,o as t,c as n,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse(`{"title":"Unlocking Ceph's Potential with NVMe oF Integration | Ceph Days London 2024","description":"","frontmatter":{"title":"Unlocking Ceph's Potential with NVMe oF Integration | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["Ceph","NVMe","oF","存储优化","分布式存储","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Unlocking_Ceph_s_Potential_with_NVMe_oF_Integration_Ceph_Days_London_2024.md","filePath":"posts/2024/Unlocking_Ceph_s_Potential_with_NVMe_oF_Integration_Ceph_Days_London_2024.md","lastUpdated":1780459816000}`),i={name:"posts/2024/Unlocking_Ceph_s_Potential_with_NVMe_oF_Integration_Ceph_Days_London_2024.md"};function p(_,e,s,a,r,N){return t(),n("div",null,[...e[0]||(e[0]=[l('<h3 id="改进后的会议纪要" tabindex="-1">改进后的会议纪要 <a class="header-anchor" href="#改进后的会议纪要" aria-label="Permalink to &quot;改进后的会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph与NVMe-oF集成潜力探讨</p><p><strong>参会人员</strong>： NVMe-oF项目成员、Ceph研发人员等</p><p><strong>会议内容</strong>：</p><p><strong>一、NVMe-oF 介绍</strong></p><ul><li>NVMe-oF是一种基于网络协议的存储访问方式，允许通过网络访问本地NVMe设备，具有高性能、低延迟和可扩展性等优点。</li><li>NVMe-oF支持多种网络协议（如TCP、iSCSI、RoCE）和NVMe设备（如NVMe SSD、NVMe-oF Target），并提供多种访问控制方式（如ACL、RBAC）。</li></ul><p><strong>二、NVMe-oF的进展</strong></p><ul><li>NVMe-oF已取得显著进展，包括支持多种网络协议、NVMe设备和访问控制方式。</li><li>NVMe-oF在网络传输中可以充分利用高速网络带宽，提高访问速度，并降低延迟。</li></ul><p><strong>三、NVMe-oF的优势</strong></p><ul><li>相比传统NVMe，NVMe-oF提供更高性能、更低延迟和更好可扩展性。</li><li>NVMe-oF易于使用硬件加速器进行卸载，减轻CPU负担。</li></ul><p><strong>四、NVMe-oF的应用场景</strong></p><ul><li>NVMe-oF适用于数据中心存储、分布式存储和云计算领域。</li></ul><p><strong>五、Ceph与NVMe-oF的集成</strong></p><ul><li>Ceph已集成NVMe-oF，支持NVMe连接、命名空间管理、访问控制和数据传输。</li><li>Ceph使用SPDK框架实现NVMe-oF，并支持NVMe连接和断开连接等功能。</li><li>Ceph支持NVMe-oF的发现服务，允许自动连接到所有目标。</li></ul><p><strong>六、高可用性</strong></p><ul><li>Ceph使用网关组实现高可用性，支持至少两个网关部署，并支持故障转移和故障恢复。</li><li>网关组中的所有网关读取相同的配置文件，并自动负载均衡命名空间。</li></ul><p><strong>七、后续行动计划</strong></p><ul><li>集成NVMe-oF CLI到Ceph主CLI中。</li><li>支持NVMe-oF In-Band消息通知。</li><li>支持子系统级别的访问控制。</li><li>支持名称空间屏蔽功能。</li><li>支持更广泛的网络协议和设备。</li><li>提高性能和可扩展性。</li></ul><p><strong>八、讨论要点</strong></p><ul><li>NVMe-oF的网络协议支持和设备支持。</li><li>NVMe-oF的访问控制方式。</li><li>NVMe-oF的性能优化方法。</li></ul><p><strong>九、会议总结</strong></p><p>NVMe-oF项目取得了显著进展，Ceph与NVMe-oF的集成为用户提供更好的存储服务。未来将继续优化NVMe-oF的性能和可扩展性，并支持更广泛的网络协议和设备。</p>',22)])])}const M=o(i,[["render",p]]);export{g as __pageData,M as default};
